function reconcileInventory(initial, events) {
  const inventory = { ...initial };
  const seen = new Set();
  for (const event of events) {
    if (seen.has(event.id)) {
      continue;
    }
    seen.add(event.id);
    for (const item of event.items) {
      if (!Object.prototype.hasOwnProperty.call(inventory, item.id)) {
        continue;
      }
      if (event.type === "sale") {
        inventory[item.id] = Math.max(0, inventory[item.id] - item.quantity);
      } else if (event.type === "return") {
        inventory[item.id] += item.quantity;
      }
    }
  }
  return inventory;
}
